package vn.edu.eaut.lab8.repository; import vn.edu.eaut.lab8.model.SinhVien; import java.util.*; public class SinhVienRepository { private static final List<SinhVien> data=new ArrayList<>(); private static int next=3; static{data.add(new SinhVien(1,"20240001","Nguyễn Văn An","an@gmail.com","DCCNTT15.10.1"));data.add(new SinhVien(2,"20240002","Trần Thị Bình","binh@gmail.com","DCCNTT15.10.2"));} public List<SinhVien> findAll(){return data;} public void add(SinhVien x){x.setId(next++);data.add(x);} public void update(SinhVien x){for(int i=0;i<data.size();i++)if(data.get(i).getId()==x.getId())data.set(i,x);} public void delete(int id){data.removeIf(x->x.getId()==id);} public SinhVien findById(int id){return data.stream().filter(x->x.getId()==id).findFirst().orElse(null);} public List<SinhVien> search(String k){if(k==null||k.isBlank())return data; final String q=k.toLowerCase();return data.stream().filter(x->x.getHoTen().toLowerCase().contains(q)||x.getLop().toLowerCase().contains(q)).toList();} }
